use serde_json::{Value, from_str};
use std::str::FromStr;

pub fn solve(input: Value) -> Value {
    if let Some(s) = input.as_str() {
        if let Ok(amount) = parse_amount(s) {
            return Value::Number(amount.into());
        }
    }
    Value::Null
}

fn parse_amount(s: &str) -> Result<i64, ()> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err(());
    }

    let parts: Vec<&str> = trimmed.split('.').collect();
    if parts.len() > 2 {
        return Err(());
    }

    let (integer_part, decimal_part) = match parts.len() {
        1 => (parts[0], ""),
        2 => parts,
        _ => return Err(()),
    };

    let integer_part = integer_part.trim_start_matches('-');
    let integer_value = i64::from_str(integer_part).map_err(|_| ())?;

    let decimal_part = decimal_part.trim_start_matches('0');
    let decimal_value = if decimal_part.is_empty() {
        0
    } else {
        i64::from_str(decimal_part).map_err(|_| ())? * 100
    };

    if integer_value > 1000000 || decimal_value > 99 {
        return Err(());
    }

    Ok(integer_value * 100 - decimal_value)
}
